export function Density({
  rowLabel = "{{rowLabel}}",
  density = "{{density}}",
  accent = "{{accent}}",
  showDividers = {{showDividers}},
}) {
  const pad = { compact: "4px 8px", comfortable: "10px 8px", spacious: "18px 8px" }[density];
  const fontSize = { compact: 12, comfortable: 14, spacious: 15 }[density];
  const rowStyle = { display: "flex", alignItems: "center", gap: 10, padding: pad, fontSize, borderBottom: showDividers ? "1px solid #24143015" : "none" };
  const dot = <span style={{ width: 8, height: 8, borderRadius: "50%", flexShrink: 0, background: accent }} />;
  return (
    <ul role="img" aria-label={`List at ${density} density`} style={{ font: "14px system-ui, sans-serif", color: "#241430", background: "#FAF7F2", width: 280, margin: 0, padding: 8, borderRadius: 12, listStyle: "none", boxSizing: "border-box" }}>
      <li style={rowStyle}>{dot}{rowLabel} one</li>
      <li style={rowStyle}>{dot}{rowLabel} two</li>
      <li style={{ ...rowStyle, borderBottom: "none" }}>{dot}{rowLabel} three</li>
    </ul>
  );
}
